contract:
trait VotingInterface {
    // State: map<string, bool> has_voted
    method CastVote(voter_id: string) returns (success: bool)
        requires !has_voted[voter_id]
        ensures success ==> has_voted[voter_id] == true
}

python:
def cast_vote(self, voter_id: str) -> bool:
    if not self.has_voted.get(voter_id, False):
        self.has_voted[voter_id] = True
        return True
    return False

